mapper.select:
SELECT E.ID AS "id" ,E.KIND AS "kind" ,E.MESSAGE AS "message" ,E.STACK AS "stack" ,E.PATH AS "path" ,E.UA AS "ua" ,E.CNT AS "cnt" ,E.STATUS AS "status" ,(EXTRACT(EPOCH FROM E.FIRST_DAY) * 1000)::BIGINT AS "firstAt" ,(EXTRACT(EPOCH FROM E.LAST_DAY) * 1000)::BIGINT AS "lastAt" FROM T_CLIENT_ERROR E WHERE 1=1
AND E.STATUS = #{status}
ORDER BY E.LAST_DAY DESC LIMIT 100
